import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"横渠易说 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"横渠易说 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/028.md","filePath":"zh/classics/hengqu/028.md"}'),l={name:"zh/classics/hengqu/028.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><h3 id="彖曰-大畜-刚健笃实辉光-日新其德。刚上而尚贤-能止健-大正也。-不家食吉-养贤也。-利涉大川-应乎天也。" tabindex="-1">彖曰：大畜，刚健笃实辉光，日新其德。刚上而尚贤，能止健，大正也。“不家食吉”，养贤也。“利涉大川”，应乎天也。 <a class="header-anchor" href="#彖曰-大畜-刚健笃实辉光-日新其德。刚上而尚贤-能止健-大正也。-不家食吉-养贤也。-利涉大川-应乎天也。" aria-label="Permalink to “彖曰：大畜，刚健笃实辉光，日新其德。刚上而尚贤，能止健，大正也。“不家食吉”，养贤也。“利涉大川”，应乎天也。”">​</a></h3><h3 id="象曰-天在山中-大畜-君子以多识前言往行以畜其德。" tabindex="-1">象曰：天在山中，大畜，君子以多识前言往行以畜其德。 <a class="header-anchor" href="#象曰-天在山中-大畜-君子以多识前言往行以畜其德。" aria-label="Permalink to “象曰：天在山中，大畜，君子以多识前言往行以畜其德。”">​</a></h3><p>刚健笃实，日新其德，乃天德也。 阳卦在上，而上九又在其上，故曰“刚上而尚贤”。强学者往往心多好胜，必无心处(一)［之］乃善也。定然后始有光明，惟能定已是光明矣，若常移易不定，何(求)［来］光明!易大抵以艮为止，止乃光明。时止时行，“动静不失其时，其道光明”，“谦天道下济而光明”，“天在山中，大畜，君子以刚健笃实辉光，日新其德”，定则自光明，故大学定而至于能虑。人心多则无由光明。(蒙杂而着着古着字杂着于物所以为蒙蒙昏蒙)</p><h3 id="初九-有厉-利己。-象曰-有厉利己-不犯灾也。" tabindex="-1">初九，有厉，利己。 象曰：“有厉利己”，不犯灾也。 <a class="header-anchor" href="#初九-有厉-利己。-象曰-有厉利己-不犯灾也。" aria-label="Permalink to “初九，有厉，利己。 象曰：“有厉利己”，不犯灾也。”">​</a></h3><p>趋其应则有二三之阻，故不若己也。</p><h3 id="九二-舆说輹。-象曰-舆说輹-中无尤也。" tabindex="-1">九二，舆说輹。 象曰：“舆说輹”，中无尤也。 <a class="header-anchor" href="#九二-舆说輹。-象曰-舆说輹-中无尤也。" aria-label="Permalink to “九二，舆说輹。 象曰：“舆说輹”，中无尤也。”">​</a></h3><p>不阻于三则见童于四，不躁进者，位中也。</p><h3 id="九三-良马逐-利艰贞。曰闲舆卫-利有攸往。-象曰-利有攸往-上合志也。" tabindex="-1">九三，良马逐，利艰贞。曰闲舆卫，利有攸往。 象曰：“利有攸往”，上合志也。 <a class="header-anchor" href="#九三-良马逐-利艰贞。曰闲舆卫-利有攸往。-象曰-利有攸往-上合志也。" aria-label="Permalink to “九三，良马逐，利艰贞。曰闲舆卫，利有攸往。 象曰：“利有攸往”，上合志也。”">​</a></h3><p>不防舆卫而进历二阴，则或有童牿说(辐)［輹］之害，不利其往也。本乎天者亲上，故上合志也。</p><h3 id="六四-童牛之牿-元吉。-象曰-六四元吉-有喜也。" tabindex="-1">六四，童牛之牿，元吉。 象曰：六四元吉，有喜也。 <a class="header-anchor" href="#六四-童牛之牿-元吉。-象曰-六四元吉-有喜也。" aria-label="Permalink to “六四，童牛之牿，元吉。 象曰：六四元吉，有喜也。”">​</a></h3><h3 id="六五-豮豕之牙-吉。-象曰-六五之吉-有庆也。" tabindex="-1">六五，豮豕之牙，吉。 象曰：六五之吉，有庆也。 <a class="header-anchor" href="#六五-豮豕之牙-吉。-象曰-六五之吉-有庆也。" aria-label="Permalink to “六五，豮豕之牙，吉。 象曰：六五之吉，有庆也。”">​</a></h3><h3 id="上九-何天之衢-亨。-象曰-何天之衢-道大行也。" tabindex="-1">上九，何天之衢，亨。 象曰：“何天之衢”，道大行也。 <a class="header-anchor" href="#上九-何天之衢-亨。-象曰-何天之衢-道大行也。" aria-label="Permalink to “上九，何天之衢，亨。 象曰：“何天之衢”，道大行也。”">​</a></h3><p>其道大行也，升于天，何待衢路而进？言无所不通也。衢字当为绝句。艮为止，止二阴也，不以止其类也，故亨。</p>',14)])])}const b=e(l,[["render",t]]);export{p as __pageData,b as default};
